// Инструмент get_inventory: считает запас в днях, статус и количество к заказу.
// Расчёт делает код, нейросеть только вызывает инструмент и формулирует ответ.
const DATA = [{"sku": "SKU-001", "name": "Чехол для iPhone 15 прозрачный", "stock": 420, "sales_30d": 310, "lead_time_days": 14, "price_kzt": 1990}, {"sku": "SKU-002", "name": "Защитное стекло для iPhone 15", "stock": 85, "sales_30d": 260, "lead_time_days": 14, "price_kzt": 1490}, {"sku": "SKU-003", "name": "Кабель USB-C 1 м", "stock": 640, "sales_30d": 180, "lead_time_days": 21, "price_kzt": 1290}, {"sku": "SKU-004", "name": "Наушники TWS Air Pro", "stock": 120, "sales_30d": 210, "lead_time_days": 25, "price_kzt": 7990}, {"sku": "SKU-005", "name": "Power bank 10000 mAh", "stock": 60, "sales_30d": 150, "lead_time_days": 25, "price_kzt": 8990}, {"sku": "SKU-006", "name": "Зарядное устройство 20 Вт", "stock": 300, "sales_30d": 95, "lead_time_days": 21, "price_kzt": 3490}, {"sku": "SKU-007", "name": "Умная лампа Wi-Fi", "stock": 75, "sales_30d": 70, "lead_time_days": 30, "price_kzt": 4590}, {"sku": "SKU-008", "name": "Коврик для мыши XL", "stock": 510, "sales_30d": 40, "lead_time_days": 14, "price_kzt": 2990}, {"sku": "SKU-009", "name": "Подставка для ноутбука", "stock": 95, "sales_30d": 120, "lead_time_days": 18, "price_kzt": 5990}, {"sku": "SKU-010", "name": "Автодержатель магнитный", "stock": 28, "sales_30d": 130, "lead_time_days": 14, "price_kzt": 2490}, {"sku": "SKU-011", "name": "Веб-камера 1080p", "stock": 70, "sales_30d": 55, "lead_time_days": 28, "price_kzt": 9990}, {"sku": "SKU-012", "name": "Клавиатура беспроводная", "stock": 150, "sales_30d": 85, "lead_time_days": 28, "price_kzt": 8490}, {"sku": "SKU-013", "name": "Мышь беспроводная", "stock": 220, "sales_30d": 160, "lead_time_days": 21, "price_kzt": 3990}, {"sku": "SKU-014", "name": "Колонка Bluetooth mini", "stock": 33, "sales_30d": 90, "lead_time_days": 30, "price_kzt": 6990}, {"sku": "SKU-015", "name": "Сетевой фильтр 5 розеток", "stock": 260, "sales_30d": 75, "lead_time_days": 14, "price_kzt": 4490}, {"sku": "SKU-016", "name": "Смарт-часы Fit", "stock": 52, "sales_30d": 48, "lead_time_days": 30, "price_kzt": 14990}, {"sku": "SKU-017", "name": "Карта памяти 128 ГБ", "stock": 190, "sales_30d": 140, "lead_time_days": 21, "price_kzt": 5490}, {"sku": "SKU-018", "name": "Ремешок для смарт-часов", "stock": 410, "sales_30d": 35, "lead_time_days": 14, "price_kzt": 1790}, {"sku": "SKU-019", "name": "Светодиодная лента 5 м", "stock": 95, "sales_30d": 115, "lead_time_days": 21, "price_kzt": 3290}, {"sku": "SKU-020", "name": "Адаптер HDMI - USB-C", "stock": 40, "sales_30d": 25, "lead_time_days": 25, "price_kzt": 6490}];

const raw = typeof query === 'string' ? query : (query && query.query) || '';
const q = String(raw).trim().toLowerCase();

const rows = DATA.map(d => {
  const daily = d.sales_30d / 30;
  const daysLeft = daily > 0 ? Math.round((d.stock / daily) * 10) / 10 : null;
  const reorder = daily > 0 ? Math.max(0, Math.ceil((d.lead_time_days + 14) * daily - d.stock)) : 0;
  let status = 'ОК';
  if (daysLeft === null) status = 'НЕТ ПРОДАЖ';
  else if (daysLeft < d.lead_time_days) status = 'СРОЧНО';
  else if (daysLeft < d.lead_time_days + 14) status = 'СКОРО';
  else if (daysLeft > 90) status = 'ЗАТОВАРКА';
  return { ...d, sales_per_day: Math.round(daily * 100) / 100, days_left: daysLeft, reorder_qty: reorder, status };
});
rows.sort((a, b) => (a.days_left ?? 1e9) - (b.days_left ?? 1e9));

const count = s => rows.filter(r => r.status === s).length;
const summary = {
  total_items: rows.length,
  urgent: count('СРОЧНО'),
  soon: count('СКОРО'),
  overstock: count('ЗАТОВАРКА'),
  total_reorder_units: rows.reduce((s, r) => s + r.reorder_qty, 0)
};

let items = rows;
if (q && q !== 'all' && q !== 'все') {
  const sku = /^\d+$/.test(q) ? 'sku-' + q.padStart(3, '0') : q;
  const found = rows.filter(r =>
    r.sku.toLowerCase() === sku || r.name.toLowerCase().includes(q) || r.status.toLowerCase() === q);
  if (found.length) items = found;
}
return JSON.stringify({ summary, items });
